new='''        class Key
        {
            public List<Panel> Panels;
            public double Tol;

            public bool Matches(Key o) => o != null && Tol == o.Tol
                && Panels.Count == o.Panels.Count && Panels.Zip(o.Panels, ReferenceEquals).All(x => x);
        }

        class Result
        {
            public List<int> Groups = new List<int>();
            public List<Panel> Reps = new List<Panel>();
        }

        readonly object _lock = new object();
        CancellationTokenSource _cts;
        Key _runningKey;
        Key _doneKey;
        Result _result;
        int _progress;

        static double[] Signature(Panel p)
        {
            var e = p.EdgeLengths(); Array.Sort(e);
            var d = p.DiagonalLengths(); Array.Sort(d);
            return e.Concat(d).ToArray();
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = GetPanels(DA, 0);
            double tol = 1.0;
            if (panels == null || !DA.GetData(1, ref tol))
            {
                Cancel();
                return;
            }
            if (tol <= 0)
            {
                Cancel();
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Tolerance must be greater than 0.");
                return;
            }
            var key = new Key { Panels = panels, Tol = tol };

            Result ready = null;
            lock (_lock)
            {
                if (_result != null && key.Matches(_doneKey)) ready = _result;
                else if (_runningKey != null && key.Matches(_runningKey))
                {
                    Message = _progress + "%";
                    return;
                }
            }

            if (ready == null)
            {
                Start(key);
                return;
            }

            Message = "";
            DA.SetDataList(0, ready.Groups);
            DA.SetData(1, ready.Reps.Count);
            DA.SetDataList(2, ready.Reps.Select(p => new GH_Panel(p)));
        }

        void Cancel()
        {
            lock (_lock)
            {
                _cts?.Cancel();
                _cts = null;
                _runningKey = null;
                _doneKey = null;
                _result = null;
            }
            Message = "";
        }

        void Start(Key key)
        {
            CancellationTokenSource cts;
            lock (_lock)
            {
                _cts?.Cancel();
                _cts = cts = new CancellationTokenSource();
                _runningKey = key;
                _doneKey = null;
                _result = null;
                _progress = 0;
            }
            Message = "0%";

            Task.Run(() =>
            {
                Result result;
                try { result = Group(key, cts.Token); }
                catch (OperationCanceledException) { return; }
                catch (Exception) { result = new Result(); }

                lock (_lock)
                {
                    if (cts.IsCancellationRequested) return;
                    _runningKey = null;
                    _doneKey = key;
                    _result = result;
                }
                RhinoApp.InvokeOnUiThread(new Action(() =>
                {
                    if (!cts.IsCancellationRequested) ExpireSolution(true);
                }));
            });
        }

        void ReportProgress(int percent, CancellationToken token)
        {
            if (percent == _progress) return;
            _progress = percent;
            RhinoApp.InvokeOnUiThread(new Action(() =>
            {
                if (token.IsCancellationRequested) return;
                Message = percent + "%";
                OnDisplayExpired(false);
            }));
        }

        Result Group(Key key, CancellationToken token)
        {
            double tol = key.Tol;
            var sigs = new List<double[]>();
            var result = new Result();
            for (int n = 0; n < key.Panels.Count; n++)
            {
                token.ThrowIfCancellationRequested();
                ReportProgress(100 * n / Math.Max(1, key.Panels.Count), token);

                var p = key.Panels[n];
                var s = Signature(p);
                int g = sigs.FindIndex(r => r.Zip(s, (a, b) => Math.Abs(a - b) <= tol).All(x => x));
                if (g < 0)
                {
                    g = sigs.Count;
                    sigs.Add(s);
                    result.Reps.Add(p);
                }
                result.Groups.Add(g);
            }
            return result;
        }

        public override void RemovedFromDocument(GH_Document document)
        {
            Cancel();
            base.RemovedFromDocument(document);
        }
    }

